"""Post-process and plot data generated by SuperConga.

Parse the data-files generated by the SuperConga runner (superconga.py), and
draw 2D or 1D plots of various observables. Which observables to plot is chosen
e.g. via command-line arguments, see the full list of arguments with the --help
flag.
"""

# Built-in modules and third-party libraries.
import matplotlib.pyplot as plt
import os
import sys

# Custom libraries.
sys.path.insert(0, os.path.join(os.path.dirname(__file__), "tools/"))
from python_libraries.file_io import parse_json_files
from python_libraries.file_io import parse_convergence
from python_libraries.file_io import parse_grid_quantity
from python_libraries.parameter_setup import argument_parsing as AP
from python_libraries.parameter_setup import argument_validation as AV
from python_libraries.plotting import field_plotting

# Global settings.


# Main.
def main() -> None:
    # =======================================================================#
    #                            ARGUMENT PARSING                            #
    # =======================================================================#
    # Use settings for a plotter frontend (frontend can be runner or plotter).
    frontend = "plotter"
    # Program name and description for command-line help message.
    program_name = "SuperConga plotter"
    program_description = "Post-process and plot data generated by SuperConga. Draw 2D or 1D plots of various observables. Which observables to plot is chosen e.g. via command-line arguments and/or json configuration file. See the full list of arguments with the --help flag."
    # Parse command-line arguments, and possibly a JSON file which specifies
    # config plotting parameters. The JSON file is provided via: -f|--file.
    plot_config_parameters, _ = AP.parse_command_line_arguments(
        program_name=program_name,
        program_description=program_description,
        frontend=frontend,
    )

    # ======================================================================#
    #                          ARGUMENT VALIDATION                          #
    # ======================================================================#
    # Validate user input (e.g. check that data path exists).
    # Exit if there are errors.
    success = AV.validate_arguments(
        arguments_dict=plot_config_parameters, frontend=frontend
    )
    if not success:
        status_code = 1
        sys.exit(status_code)

    # ======================================================================#
    #                           PARSE DATA FILES                            #
    # ======================================================================#
    # Parse simulation parameters from json, get result as dictionary. Example:
    # simulation_parameters['temperature'] gives the temperature (in T_c).
    simulation_parameters = parse_json_files.parse_config(
        base_path=plot_config_parameters["general"]["data_path"]
    )
    # To see all available parameters, print with e.g.:
    # pprint.pprint(simulation_parameters)

    # Get geometry mask.
    geometry = parse_grid_quantity.parse_geometry_numpy(
        base_path=plot_config_parameters["general"]["data_path"]
    )

    # Parse "internal parameters" from json, get result as dictionary.
    # Internal parameters are calculated by the framework, as opposed to
    # "simulation parameters" set by the user before simulation. Example:
    # internal_parameters['internal_lattice_points'] gives the number of
    # discrete lattice points inside the grain, which can be multiplied by
    # simulation_parameters['points_per_coherence_length']**2 to get the
    # area in (coherence length)^2.
    internal_parameters = parse_json_files.parse_internal_parameters(
        base_path=plot_config_parameters["general"]["data_path"]
    )
    # To see all available parameters, print with e.g.:
    # pprint.pprint(internal_parameters)

    # Parse scalar results from json, get result as dictionary. Example:
    # scalar_results['free_energy_per_unit_area'] gives the area-averaged free
    # energy in units of N_F*(coherence length)^2*(k_B*T_c)^2.
    scalar_results = parse_json_files.parse_scalar_results(
        base_path=plot_config_parameters["general"]["data_path"]
    )
    # To see all available parameters, print with e.g.:
    # pprint.pprint(scalar_results)

    # Parse convergence data from csv. Convergence data contains iteration
    # number, residual of various observables, and the area-averaged free
    # energy. The convergence data is a pandas DataFrame, where each csv column
    # is accessible via the column name. Example: convergence_data['iteration']
    # gives the iteration numbers. The column names can be obtained as a list
    # of strings and printed with print(convergence_data.columns).
    convergence_data = parse_convergence.parse_convergence_csv(
        base_path=plot_config_parameters["general"]["data_path"]
    )

    # Parse all 2D grid observables/quantities, as a dictionary of either 2D
    # numpy arrays (convenient for matplotlib) or pandas dataframes. The data
    # is accessible as: data['field']['component'], where 'field' is e.g.
    # 'current_density', 'magnetic_flux_density', or 'order_parameter'.
    # See all available fields with: print(data.keys())
    # Here, 'component' is any of:
    # 'magnitude' or 'phase' for complex fields (the order parameter),
    # 'magnitude' for scalar fields (the magnetic flux density),
    # 'magnitude', 'x' or 'y' for vector fields (e.g. current density).
    # The 2D numpy array data is arranged according to
    # data['field']['component][y_idx,x_idx], where y_idx and x_idx are
    # the discrete indices for data at x- and y-coordinates given by
    # y = (y_idx / simulation_parameters['points_per_coherence_length'])
    # To get an order-parameter slice/cut at fixed y, use:
    # op_slice = data['order_parameter']['magnitude'][y_idx,:]
    data = parse_grid_quantity.parse_all_fields(
        base_path=plot_config_parameters["general"]["data_path"]
    )

    # ======================================================================#
    #                               PLOT DATA                               #
    # ======================================================================#
    # Plot all observables/quantities (that have been chosen for plotting), as
    # a collage of 2D heatmaps, via matplotlibs imshow() method.
    field_plotting.plot_all(
        data=data,
        geometry=geometry,
        plot_parameters=plot_config_parameters,
        simulation_parameters=simulation_parameters,
    )

    # Show plot windows.
    plt.show()

    # Exit Python program.
    status_code = 0
    sys.exit(status_code)


if __name__ == "__main__":
    main()
